		for mut node in nodes {
			node.books = found[node.author.id.str()] or { [] }
			node.loaded << 'books'
		}
	}
	for name, fns in q.named_books {
		found := q.load_books(rows, fns)!
		for mut node in nodes {
			node.named_books[name] = found[node.author.id.str()] or { [] }
		}
	}
	return nodes
}

// load_books loads the `books` of `rows`, keyed by each row's key.
fn (q AuthorQuery) load_books(rows []models.Author, fns []fn (BookQuery) BookQuery) !map[string][]BookNode {
	mut sub := q.graph.books()
	for configure in fns {
		sub = configure(sub)
	}
	if sub.query.limit > 0 || sub.query.offset > 0 {
		prepared := q.graph.client.prepare_edge_query('books', sub.query)!
		cut := load.link_each(q.graph.client.conn, 'book_authors', 'author_id', 'book_id',
			rows.map(it.id.str()), .int, .int, 'books', 'id', load.Query{
				...prepared
				conds: prepared.conds
			})!
		// the targets by key: the join rows give their order
		found := sub.nodes(load.select_in[models.Book](q.graph.client.conn, 'id',
			load.unique(cut.map(it[1])),
			query: load.Query{ ...prepared, order: '', desc: false, orders: []load.Order{}, limit: 0, offset: 0 }
		)!)!
		mut by_key := map[string]BookNode{}
		for target in found {
			by_key[target.book.id.str()] = target
		}
		mut cut_linked := map[string][]BookNode{}
		for pair in cut {
			if target := by_key[pair[1]] {
				cut_linked[pair[0]] << target
			}
		}
		return cut_linked
	}
	pairs := load.link_pairs(q.graph.client.conn, 'book_authors', 'author_id',
		'book_id', rows.map(it.id.str()), .int, .int)!
	// each parent's targets in the order of the query: one select per group of
	// parents, so each parent's order comes from one statement
	mut linked := map[string][]BookNode{}
	for group in load.parent_groups(pairs) {
		targets := sub.nodes(load.select_in[models.Book](q.graph.client.conn, 'id',
			load.unique(group.map(it[1])),
			query: q.graph.client.prepare_edge_query('books', sub.query)!
		)!)!
		mut parents_of := map[string][]string{}
		for pair in group {
			parents_of[pair[1]] << pair[0]
		}
		for target in targets {
			for parent in parents_of[target.book.id.str()] or { [] } {
				linked[parent] << target
			}
		}
	}
	return linked
}

// books_or_err returns the `books`, or a `NotLoadedError` when the query
// didn't load them.
pub fn (n AuthorNode) books_or_err() ![]BookNode {
	if 'books' !in n.loaded {
		return NotLoadedError{
			edge: 'authors.books'
		}
	}
	return n.books
}

// query_books starts a query of this row's `books`. It reads the join
// table `book_authors` first, so it can fail.
pub fn (n AuthorNode) query_books() !BookQuery {
	pairs := load.link_pairs(n.graph.client.conn, 'book_authors', 'author_id',
		'book_id', [n.author.id.str()], .int, .int)!
	return n.graph.books().where(load.in_keys('id', pairs.map(it[1]), .int))
}
